-- Reference schema; the app creates these tables automatically in Database.java.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('ADMIN','STUDENT')), display_name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS subjects (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, credits INTEGER NOT NULL DEFAULT 3);
CREATE TABLE IF NOT EXISTS grades (id INTEGER PRIMARY KEY AUTOINCREMENT, subject_id INTEGER NOT NULL, cie REAL NOT NULL DEFAULT 0, ese REAL NOT NULL DEFAULT 0, target_grade TEXT NOT NULL DEFAULT 'B', FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS attendance (id INTEGER PRIMARY KEY AUTOINCREMENT, subject_id INTEGER NOT NULL, classes_held INTEGER NOT NULL DEFAULT 0, classes_attended INTEGER NOT NULL DEFAULT 0, FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS assessments (id INTEGER PRIMARY KEY AUTOINCREMENT, subject_id INTEGER NOT NULL, title TEXT NOT NULL, max_marks REAL NOT NULL DEFAULT 10, marks_obtained REAL NOT NULL DEFAULT 0, due_date TEXT DEFAULT '', FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS timetable (id INTEGER PRIMARY KEY AUTOINCREMENT, day TEXT NOT NULL, period INTEGER NOT NULL, subject_id INTEGER, start_time TEXT NOT NULL DEFAULT '', end_time TEXT NOT NULL DEFAULT '', room TEXT NOT NULL DEFAULT '', FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE SET NULL);
